# Turns the chosen fixture rows into the SQL text of the local fixture (work pack D-14).
# Runs after select_fixture_rows.py. infra/local/setup.sh loads the file with psql after the
# migrations, so the SQL must work on an empty database and be safe to load twice.

import json
from collections.abc import Sequence

from local_fixture.fixture_rows import FixtureEntity, FixtureSource

STORAGE_SRID = 4326

FILE_HEADER = """\
-- Local fixture for the Navuuna stack (work pack D-14, Bible §14.11): a small real subset of
-- the Nairobi base layers. GENERATED by `python -m local_fixture.build_local_fixture` in
-- services/ingest. Do not edit by hand; build it again instead. See data/fixtures/README.md.
-- Safe to load twice: a row whose name or external_ref already exists is skipped.
--
-- Map data (c) OpenStreetMap contributors, Open Database Licence (ODbL) 1.0.
-- Ward boundaries digitised by FAO Kenya from IEBC maps, via HDX (CC BY); not an official
-- boundary layer. County boundary: IEBC and KNBS, via HDX (CC BY-IGO).
-- Outlines are simplified, so areas here are slightly coarser than on staging.
"""

INSERT_SOURCES_HEAD = """
INSERT INTO core.sources (name, kind, base_url, licence, attribution)
VALUES
"""
INSERT_SOURCES_TAIL = "\nON CONFLICT (name) DO NOTHING;\n"

# Each entity finds its source and its parent area by name while loading, because their ids
# differ from one database to the next. Parents are loaded by an earlier statement.
INSERT_ENTITIES_HEAD = """
INSERT INTO core.entities
    (id, entity_type, module, name, external_ref, geom, radius_m, metadata, parent_area_id)
SELECT fixture.id::uuid, fixture.entity_type, fixture.module, fixture.name, fixture.external_ref,
       public.ST_GeomFromText(fixture.geometry_wkt, {storage_srid}), fixture.radius_m::float8,
       fixture.metadata::jsonb || jsonb_build_object('source_id', source.id), parent_area.id
FROM (VALUES
"""
INSERT_ENTITIES_TAIL = """
) AS fixture (id, entity_type, module, name, external_ref, geometry_wkt, radius_m, metadata,
              parent_external_ref, source_name)
JOIN core.sources AS source ON source.name = fixture.source_name
LEFT JOIN core.entities AS parent_area ON parent_area.external_ref = fixture.parent_external_ref
ON CONFLICT (external_ref) DO NOTHING;
"""


def write_fixture_sql(
    sources: Sequence[FixtureSource], entity_groups: Sequence[Sequence[FixtureEntity]]
) -> str:
    """Return the whole fixture file as SQL text.

    Inputs: the sources, and the entities in groups that are loaded one after the other —
    a group may only have parents from an earlier group. Output: the SQL text.
    Implements Bible §14.11 (local data is a committed SQL fixture).
    """
    statements = [FILE_HEADER, write_sources_statement(sources)]
    for entities in entity_groups:
        statements.append(write_entities_statement(entities))
    return "".join(statements)


def write_sources_statement(sources: Sequence[FixtureSource]) -> str:
    """Return the INSERT that stores the fixture's sources."""
    value_rows = [
        "    ("
        + ", ".join(
            quote_sql_text(value)
            for value in (
                source.name,
                source.kind,
                source.base_url,
                source.licence,
                source.attribution,
            )
        )
        + ")"
        for source in sources
    ]
    return INSERT_SOURCES_HEAD + ",\n".join(value_rows) + INSERT_SOURCES_TAIL


def write_entities_statement(entities: Sequence[FixtureEntity]) -> str:
    """Return the INSERT that stores one group of entities, one entity per line."""
    value_rows = ["    " + write_entity_values(entity) for entity in entities]
    head = INSERT_ENTITIES_HEAD.format(storage_srid=STORAGE_SRID)
    return head + ",\n".join(value_rows) + INSERT_ENTITIES_TAIL


def write_entity_values(entity: FixtureEntity) -> str:
    """Return one entity as a bracketed list of SQL text values, in column order."""
    radius_text = None if entity.radius_m is None else str(entity.radius_m)
    values = (
        entity.id,
        entity.entity_type,
        entity.module,
        entity.name,
        entity.external_ref,
        entity.geometry_wkt,
        radius_text,
        json.dumps(entity.metadata, sort_keys=True),
        entity.parent_external_ref,
        entity.source_name,
    )
    return "(" + ", ".join(quote_sql_text(value) for value in values) + ")"


def quote_sql_text(value: str | None) -> str:
    """Return a value as a SQL text literal, or NULL when there is none.

    A single quote inside the value is doubled, which is all PostgreSQL needs: names such
    as "Sarang'ombe" would otherwise end the literal early.
    """
    if value is None:
        return "NULL"
    return "'" + value.replace("'", "''") + "'"
